PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, username TEXT UNIQUE, display_username TEXT, role TEXT NOT NULL DEFAULT 'composer' CHECK(role IN ('composer','admin')));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verifications (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS composers (id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL COLLATE NOCASE UNIQUE, slug TEXT NOT NULL UNIQUE, bio TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '', contact_url TEXT NOT NULL DEFAULT '', private_email TEXT NOT NULL DEFAULT '', notice TEXT NOT NULL DEFAULT '', sample INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS arrangements (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, composer_id TEXT NOT NULL REFERENCES composers(id), description TEXT NOT NULL DEFAULT '', lyrics TEXT NOT NULL DEFAULT '', voicing TEXT NOT NULL DEFAULT '', difficulty TEXT NOT NULL DEFAULT 'Intermediate', original INTEGER NOT NULL DEFAULT 0, hymn TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL DEFAULT '', youtube_id TEXT NOT NULL DEFAULT '', available_at INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1, winner INTEGER NOT NULL DEFAULT 0, thumbnail TEXT NOT NULL DEFAULT '/fixtures/score.svg', sample INTEGER NOT NULL DEFAULT 0, rights_attested INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX IF NOT EXISTS arrangements_composer ON arrangements(composer_id,published,available_at);
CREATE INDEX IF NOT EXISTS arrangements_recent ON arrangements(published,available_at,created_at);
CREATE TABLE IF NOT EXISTS credits (arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, composer_id TEXT NOT NULL REFERENCES composers(id), PRIMARY KEY(arrangement_id,composer_id));
CREATE TABLE IF NOT EXISTS aliases (code TEXT PRIMARY KEY, arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, type TEXT NOT NULL DEFAULT 'topic', parent_id TEXT REFERENCES tags(id) ON DELETE SET NULL, rank INTEGER NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT '', rights_warning TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS arrangement_tags (arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(arrangement_id,tag_id));
CREATE INDEX IF NOT EXISTS tags_arrangements ON arrangement_tags(tag_id,arrangement_id);
CREATE VIRTUAL TABLE IF NOT EXISTS arrangement_search USING fts5(arrangement_id UNINDEXED,title,composer,tags,description,code,tokenize='unicode61 remove_diacritics 2',prefix='2 3 4');
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, arrangement_id TEXT REFERENCES arrangements(id) ON DELETE SET NULL, owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, storage_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), state TEXT NOT NULL DEFAULT 'staged' CHECK(state IN ('staged','published','failed','deleted')), kind TEXT NOT NULL DEFAULT 'attachment', rank INTEGER NOT NULL DEFAULT 0, parent_id TEXT REFERENCES files(id) ON DELETE SET NULL, provenance TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS files_arrangement ON files(arrangement_id,state,rank);
CREATE TABLE IF NOT EXISTS upload_tickets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, storage_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'reserved', upload_id TEXT, parts TEXT NOT NULL DEFAULT '[]', expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS storage_quota (id TEXT PRIMARY KEY, used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0), max_bytes INTEGER NOT NULL);
INSERT OR IGNORE INTO storage_quota(id,max_bytes) VALUES('preview',1073741824);
CREATE TABLE IF NOT EXISTS bookmarks (session_id TEXT NOT NULL, arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), PRIMARY KEY(session_id,arrangement_id));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', text TEXT NOT NULL, rating REAL CHECK(rating IS NULL OR rating BETWEEN 1 AND 5), difficulty INTEGER CHECK(difficulty IS NULL OR difficulty BETWEEN 1 AND 5), created_at INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 1, dedupe_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS competitions (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', opens_at INTEGER NOT NULL, closes_at INTEGER NOT NULL, year INTEGER NOT NULL DEFAULT 2026, CHECK(closes_at>opens_at));
CREATE TABLE IF NOT EXISTS competition_entries (competition_id TEXT NOT NULL REFERENCES competitions(id) ON DELETE CASCADE, arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, PRIMARY KEY(competition_id,arrangement_id));
CREATE TABLE IF NOT EXISTS votes (id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES competitions(id) ON DELETE CASCADE, arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, household_key TEXT NOT NULL, session_id TEXT NOT NULL, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, rating REAL CHECK(rating IS NULL OR rating BETWEEN 1 AND 5), feedback TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, counts INTEGER NOT NULL DEFAULT 1, UNIQUE(competition_id,arrangement_id,household_key), UNIQUE(competition_id,arrangement_id,session_id), UNIQUE(competition_id,arrangement_id,user_id));
CREATE TABLE IF NOT EXISTS pages (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, body TEXT NOT NULL, section TEXT NOT NULL DEFAULT 'pages', rank INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS preferences (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'captured', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mail_outbox (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'transactional', status TEXT NOT NULL DEFAULT 'captured', attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, expires_at INTEGER);
CREATE TABLE IF NOT EXISTS stats (arrangement_id TEXT NOT NULL REFERENCES arrangements(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('view','download','referral')), count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(arrangement_id,kind));
CREATE TABLE IF NOT EXISTS counted_events (event_key TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, target_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS processing_jobs (id TEXT PRIMARY KEY, arrangement_id TEXT REFERENCES arrangements(id) ON DELETE CASCADE, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', detail TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, window_end INTEGER NOT NULL);
